 { id: 'T-3001', question: 'Can I set environment variables per workflow in n8n Cloud?', aiAnswer: 'Yes. Open the workflow settings panel and add environment variables for that workflow.' },
 { id: 'T-3002', question: 'My webhook returns 404 in production but works in test', aiAnswer: 'Your workflow is not active. Publish/activate the workflow and use the production URL rather than the test URL.' },
 { id: 'T-3003', question: 'How do I rotate my API key?', aiAnswer: 'Go to Settings, then API, and delete the old key. You can create a new key there.' }
] } }];

const raw = $input.first().json.output ?? '';
const match = String(raw).match(/\{[\s\S]*\}/);
let audits = [];
try { audits = JSON.parse(match ? match[0] : raw).audits || []; } catch (e) { audits = []; }
const bad = audits.filter(a => a.verdict !== 'correct');
const rate = audits.length ? Math.round(100 * bad.length / audits.length) : 0;
let body = 'AI agent QA audit (today sample of ' + audits.length + ' agent-closed tickets):\n\nFalse/incomplete resolution rate: ' + rate + '%\n\n';
for (const a of audits) body += '[' + a.verdict.toUpperCase() + '] ' + a.id + '\n  ' + a.why + '\n  Follow-up: ' + a.humanFollowUp + '\n\n';
body += 'Why this exists: deflection only counts if the answer was right. This audit is the difference between 80% deflection and 80% deflection you can trust.';
return [{ json: { subject: 'AI agent QA: ' + rate + '% flagged today', body } }];
